INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", 10, "", 302, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 11, 13020019, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (5, "", "", "", "", "", 302, "", 93, 13020020, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", "", "", 302, 0, 4, 13020021, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", 0.2, "", 1, "", 302, "nyx_cmn_03", 3, 13020022, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", 10, "", 302, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 11, 13020023, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0, "", "", "", "", "", 302, "", 91, 13020024, "");
