INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", 10, "", 302, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 11, 13020026, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0, "", "", "", "", "", 302, 1, 91, 13020027, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", 10, "", 302, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 11, 13020028, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0, "", "", "", "", "", 302, 1, 91, 13020029, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", 0.2, 1, 0, "nyx_302_yuni_04", 302, "nyx_302_yuni_03", 3, 13020030, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (111031, "", "", "", 10, "", 302, "是非もなし\nいざ往かん！", 11, 13020031, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0, "", "", "", "", "", 302, 1, 91, 13020032, "");
